package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class UiPressure167Test {
 LibraryUi163Test f;
 @Before public void setup()throws Exception{f=new LibraryUi163Test();f.setup();}
 @After public void cleanup(){f.cleanup();ResidentChecks.resetForTest();}
 @Test public void merelyHidingUiDoesNotDestroyItsTree()throws Exception{ActivityController<LibraryUi163Test.FakeMain> ctrl=f.screen("likes","");ctrl.start().resume();try{Object root=f.field(ctrl.get(),"root"),lib=f.field(ctrl.get(),"lib");ctrl.pause().stop();ctrl.get().onTrimMemory(ComponentCallbacks2.TRIM_MEMORY_UI_HIDDEN);assertSame(root,f.field(ctrl.get(),"root"));assertSame(lib,f.field(ctrl.get(),"lib"));assertFalse((Boolean)f.field(ctrl.get(),"uiEvicted"));}finally{ctrl.destroy();}}
 @Test public void memoryPressureDropsHiddenUiButNotPlayerAndRestoresScreen()throws Exception{ActivityController<LibraryUi163Test.FakeMain> ctrl=f.screen("likes","");ctrl.start().resume();PlaybackService service=new PlaybackService();service.current="sc:1";PlaybackService.instance=service;try{ctrl.pause().stop();ctrl.get().onTrimMemory(ComponentCallbacks2.TRIM_MEMORY_RUNNING_LOW);assertTrue((Boolean)f.field(ctrl.get(),"uiEvicted"));assertNull(f.field(ctrl.get(),"root"));assertNull(f.field(ctrl.get(),"lib"));assertSame(service,PlaybackService.instance);assertEquals("sc:1",service.current);ctrl.restart().start().resume();f.waitFor(ctrl.get());assertFalse((Boolean)f.field(ctrl.get(),"uiEvicted"));assertNotNull(f.field(ctrl.get(),"root"));assertEquals("library",f.field(ctrl.get(),"page"));assertEquals("likes",f.field(ctrl.get(),"filter"));assertEquals(2,((java.util.List<?>)f.field(ctrl.get(),"visible")).size());ctrl.pause().stop();}finally{PlaybackService.instance=null;ctrl.destroy();}}
 @Test public void visibleUiStaysUsableDuringMemoryPressure()throws Exception{ActivityController<LibraryUi163Test.FakeMain> ctrl=f.screen("likes","");ctrl.start().resume();try{Object root=f.field(ctrl.get(),"root");ctrl.get().onTrimMemory(ComponentCallbacks2.TRIM_MEMORY_RUNNING_CRITICAL);assertSame(root,f.field(ctrl.get(),"root"));assertFalse((Boolean)f.field(ctrl.get(),"uiEvicted"));}finally{ctrl.pause().stop().destroy();}}
}
